// generated by gemini-3.5-flash-lite for PR #5822 (round 0): test_string_boundary_stride_lengths
// intent: Probe strings of varying lengths around typical bulk scanner block strides containing control characters.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main() {
    for (std::size_t len = 1; len <= 64; ++len) {
        std::string s(len, 'a');
        if (len % 5 == 0) s[len - 1] = '\n';
        nlohmann::json j = s;
        std::cout << len << ": " << j.dump().length() << std::endl;
    }
    return 0;
}
